#!/usr/bin/env python3
"""Execute production tap geometry and preference semantics with narrow Android doubles."""
from pathlib import Path
import os,shutil,subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
JAVA=Path(os.environ['JAVA_HOME'])/'bin' if os.environ.get('JAVA_HOME') else Path(shutil.which('javac')).parent
STUBS={
'android/util/AttributeSet.java':'package android.util;public interface AttributeSet{}',
'android/util/DisplayMetrics.java':'package android.util;public class DisplayMetrics{public float density=1;public int heightPixels=800;}',
'android/content/res/Configuration.java':'package android.content.res;public class Configuration{public java.util.Locale locale=java.util.Locale.ENGLISH;}',
'android/content/res/Resources.java':'package android.content.res;public class Resources{public Configuration configuration=new Configuration();public Configuration getConfiguration(){return configuration;}public android.util.DisplayMetrics getDisplayMetrics(){return new android.util.DisplayMetrics();}}',
'android/content/Context.java':'package android.content;public class Context{public SharedPreferences prefs=new SharedPreferences();public android.content.res.Resources resources=new android.content.res.Resources();public android.content.res.Resources getResources(){return resources;}}',
'android/content/SharedPreferences.java':'''package android.content;import java.util.*;public class SharedPreferences{public Map<String,Object> values=new HashMap<>();public int writes;public boolean fail;public int getInt(String k,int d){if(fail)throw new IllegalStateException();Object v=values.get(k);return v==null?d:(Integer)v;}public Editor edit(){return new Editor();}public class Editor{String key;int val;public Editor putInt(String k,int v){key=k;val=v;return this;}public void apply(){values.put(key,val);writes++;}}}''',
'android/content/DialogInterface.java':'package android.content;public interface DialogInterface{interface OnClickListener{void onClick(DialogInterface d,int w);}}',
'android/preference/PreferenceManager.java':'package android.preference;public class PreferenceManager{public static android.content.SharedPreferences getDefaultSharedPreferences(android.content.Context c){return c.prefs;}}',
'android/preference/Preference.java':'package android.preference;import android.content.*;import android.util.*;public class Preference{Context c;public String title,summary;public boolean persistent=true;public Preference(Context c,AttributeSet a){this.c=c;}public Context getContext(){return c;}public void setPersistent(boolean b){persistent=b;}public void setTitle(CharSequence s){title=s.toString();}public void setSummary(CharSequence s){summary=s.toString();}protected void onClick(){}}',
'android/view/View.java':'package android.view;import android.content.*;public class View{Context c;public View(Context c){this.c=c;}public Context getContext(){return c;}public void setContentDescription(CharSequence s){}public void invalidate(){}public int getWidth(){return 300;}public int getHeight(){return 150;}protected void onDraw(android.graphics.Canvas c){}}',
'android/view/ViewGroup.java':'package android.view;public class ViewGroup extends View{public ViewGroup(android.content.Context c){super(c);}public static class LayoutParams{public static final int MATCH_PARENT=-1,WRAP_CONTENT=-2;public LayoutParams(int w,int h){}}}',
'android/widget/LinearLayout.java':'package android.widget;import android.content.*;import android.view.*;public class LinearLayout extends ViewGroup{public static final int VERTICAL=1;public LinearLayout(Context c){super(c);}public void setOrientation(int i){}public void setPadding(int a,int b,int c,int d){}public void addView(View v){}public void addView(View v,ViewGroup.LayoutParams p){}public static class LayoutParams extends ViewGroup.LayoutParams{public LayoutParams(int w,int h){super(w,h);}}}',
'android/widget/RadioButton.java':'package android.widget;import android.content.*;import android.view.*;public class RadioButton extends View{public RadioButton(Context c){super(c);}public void setId(int id){}public void setText(CharSequence s){}public void setTextSize(float f){}public void setMinHeight(int h){}public void setPadding(int a,int b,int c,int d){}}',
'android/widget/RadioGroup.java':'package android.widget;import android.content.*;public class RadioGroup extends LinearLayout{public static RadioGroup last;public int checked;OnCheckedChangeListener l;public RadioGroup(Context c){super(c);last=this;}public void check(int id){checked=id;if(l!=null)l.onCheckedChanged(this,id);}public void setOnCheckedChangeListener(OnCheckedChangeListener l){this.l=l;}public interface OnCheckedChangeListener{void onCheckedChanged(RadioGroup g,int id);}public static class LayoutParams extends LinearLayout.LayoutParams{public LayoutParams(int w,int h){super(w,h);}}}',
'android/widget/ScrollView.java':'package android.widget;import android.content.*;public class ScrollView extends LinearLayout{public ScrollView(Context c){super(c);}public void setFillViewport(boolean b){}}',
'android/widget/Toast.java':'package android.widget;public class Toast{public static final int LENGTH_SHORT=0;public static Toast makeText(android.content.Context c,CharSequence s,int d){return new Toast();}public void show(){}}',
'android/graphics/Color.java':'package android.graphics;public class Color{public static final int WHITE=-1,BLACK=0xff000000;}',
'android/graphics/Canvas.java':'package android.graphics;public class Canvas{public void drawRect(float a,float b,float c,float d,Paint p){}public void drawText(String s,float a,float b,Paint p){}}',
'android/graphics/Paint.java':'package android.graphics;public class Paint{public static final int ANTI_ALIAS_FLAG=1;public enum Style{FILL,STROKE}public enum Align{CENTER}public Paint(int flags){}public void setStyle(Style s){}public void setColor(int c){}public void setAntiAlias(boolean a){}public void setStrokeWidth(float w){}public void setTextAlign(Align a){}public void setTextSize(float f){}public float ascent(){return -8;}public float descent(){return 2;}}',
'android/app/AlertDialog.java':'package android.app;import android.content.*;import android.view.*;public class AlertDialog{public static DialogInterface.OnClickListener positive,negative;public static class Builder{public Builder(Context c){}public Builder setTitle(CharSequence s){return this;}public Builder setView(View v){return this;}public Builder setNegativeButton(CharSequence s,DialogInterface.OnClickListener l){negative=l;return this;}public Builder setPositiveButton(CharSequence s,DialogInterface.OnClickListener l){positive=l;return this;}public void show(){}}}',
}
with tempfile.TemporaryDirectory(prefix='quickpic-tap-host-') as work:
 t=Path(work);sources=[]
 for name,body in STUBS.items():
  p=t/'src'/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body);sources.append(p)
 sources += [ROOT/'src/com/alensw/jni/TapPageLayout.java',ROOT/'src/com/alensw/jni/TapPagePreference.java',Path(__file__).with_name('LayoutProbe.java'),Path(__file__).with_name('PreferenceProbe.java')]
 subprocess.run([str(JAVA/'javac'),'--release','8','-encoding','UTF-8','-d',str(t/'classes'),*map(str,sources)],check=True)
 for probe in ['LayoutProbe','PreferenceProbe']:subprocess.run([str(JAVA/'java'),'-cp',str(t/'classes'),probe],check=True)
